use circular_buffer::CircularBuffer;

#[test]
fn test_basic_push_pop() {
    let mut cb: CircularBuffer<i32> = CircularBuffer::new(3);
    assert!(cb.is_empty());
    cb.push(1);
    cb.push(2);
    cb.push(3);
    assert!(cb.is_full());
    assert_eq!(cb.len(), 3);
    assert_eq!(cb.pop(), Some(1));
    assert_eq!(cb.pop(), Some(2));
    assert_eq!(cb.pop(), Some(3));
    assert_eq!(cb.pop(), None);
}

#[test]
fn test_overwrite_on_full() {
    let mut cb: CircularBuffer<i32> = CircularBuffer::new(3);
    cb.push(1);
    cb.push(2);
    cb.push(3);
    cb.push(4); // overwrites 1
    assert_eq!(cb.len(), 3);
    assert_eq!(cb.pop(), Some(2));
    assert_eq!(cb.pop(), Some(3));
    assert_eq!(cb.pop(), Some(4));
}

#[test]
fn test_interleaved() {
    let mut cb: CircularBuffer<i32> = CircularBuffer::new(3);
    cb.push(10);
    cb.push(20);
    assert_eq!(cb.pop(), Some(10));
    cb.push(30);
    cb.push(40);
    assert_eq!(cb.len(), 3);
    assert_eq!(cb.pop(), Some(20));
    assert_eq!(cb.pop(), Some(30));
}
